function StrokeIcon({
  viewBox,
  children
}: {
  viewBox: string;
  children: ReactNode;
}) {
  return (
    <svg viewBox={viewBox} aria-hidden="true">
      {children}
    </svg>
  );
}

function FillIcon({
  viewBox,
  children
}: {
  viewBox: string;
  children: ReactNode;
}) {
  return (
    <svg viewBox={viewBox} aria-hidden="true" data-icon-mode="fill">
      {children}
    </svg>
  );
}

function TravelToneIcon({
  viewBox,
  children
}: {
  viewBox: string;
  children: ReactNode;
}) {
  return (
    <svg viewBox={viewBox} aria-hidden="true" data-icon-mode="travel-tone">
      {children}
    </svg>
  );
}

function StrokeDetailIcon({
  viewBox,
  children
}: {
  viewBox: string;
  children: ReactNode;
}) {
  return (
    <svg viewBox={viewBox} aria-hidden="true" data-icon-mode="stroke-detail">
      {children}
    </svg>
  );
}

